"""
    Melts several dicts into one. Useful when messing with feed dicts
    :param dicts: dictionaries
    :param check_conflicts: if True, raises error if several dicts have the same key
                    Otherwise uses the key from the latest dict in *dicts
    :return: a dict that contains k-v pairs from  all *dicts
    """
def merge_dicts(*dicts: Any, **kwargs: Any) -> object {
    merged_dict = {};
    for d in dicts {
        merged_dict.update(d);
    }
    if kwargs.get('check_conflicts') {
        assert (len(merged_dict) == sum(map(len, dicts))) , 'dicts have duplicate keys';
    }
    return merged_dict;
}

"""
    Strip off .so or .dylib.

    >>> _remove_suffix_apple("libpython.so")
    'libpython'
    >>> _remove_suffix_apple("libpython.dylib")
    'libpython'
    >>> _remove_suffix_apple("libpython3.7")
    'libpython3.7'
    """
def _remove_suffix_apple(path: Any) -> object {
    if path.endswith(".dylib") {
        return path[:-len(".dylib")];
    }
    if path.endswith(".so") {
        return path[:-len(".so")];
    }
    return path;
}

