"""
    Adds escape characters for a string.
    """
def clean(s: Any) -> object {
    s = s.replace(r'{', r'\{');
    s = s.replace(r'}', r'\}');
    s = s.replace(r'_', r'\_');
    s = s.replace(r'%', r'\%');
    return s;
}

"""
    Convert a time specification on the form hh:mm to minutes.
    >>> to_minutes('8:05')
    485
    """
def to_minutes(s: Any) -> object {
    (h, m) = s.split(':');
    return ((int(h) * 60) + int(m));
}

""" Return a splglob that either matches a full path or match a simple file """
def splglob_simple(pattern: Any) -> object {
    if ("/" not in pattern) {
        pattern = "^.../{}$".format(pattern);
    } else {
        pattern = "^{}$".format(pattern);
    }
    return pattern;
}

